package com.bank.batch;

import java.math.BigDecimal;
import java.util.logging.*;

public class BatchLauncher {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    // public  → JVM (outside this package) can invoke it
    // static  → JVM calls it with NO instance of BatchLauncher created
    // void    → no in-program caller receives a return value
    // String[]→ command-line arguments passed at launch
    public static void main(String[] args) {
        // args is NEVER null; it is empty (length 0) when no arguments are supplied.
        String profile   = args.length > 0 ? args[0] : "dev";      // default profile
        String accountId = args.length > 1 ? args[1] : "SAV2001";  // default: Rajesh

        log.info(() -> "Launched with " + args.length + " argument(s)");
        log.info(() -> "Profile   = " + profile);
        log.info(() -> "AccountId = " + accountId);

        // Because main is static, it can run immediately and then create the first objects.
        BatchLauncher launcher = new BatchLauncher(); // first instance created INSIDE main
        launcher.runSettlement(profile, accountId);

        // Normal return ends the main thread; use System.exit(code) to signal the OS explicitly.
        log.info("Batch complete — main returning (exit status 0 by default).");
    }

    // Instance method: the real work, callable only after an object exists.
    void runSettlement(String profile, String accountId) {
        BigDecimal amount = new BigDecimal("50000.00");
        log.info(() -> "[" + profile + "] Settling Rs." + amount + " for account " + accountId);
        // ... real settlement logic would run here
    }
}
